package org.elasticsearch.xpack.security.cli.bc;

import org.bouncycastle.pkcs.PKCS10CertificationRequest;

/**
 * A PKCS#10 certificate signing request, as generated by {@link CertGenUtils#generateCSR}. It can be written in PEM format with
 * {@link PemWriter#writeObject(CertificateSigningRequest)}.
 * <p>
 * This is an opaque handle for a Bouncy Castle {@code PKCS10CertificationRequest} so that callers outside this module do not depend
 * on Bouncy Castle types, which are shaded into this module's jar.
 * </p>
 */
public final class CertificateSigningRequest {

    private final PKCS10CertificationRequest request;

    CertificateSigningRequest(PKCS10CertificationRequest request) {
        this.request = request;
    }

    PKCS10CertificationRequest request() {
        return request;
    }
}
